    class ProfileManager:
    
        def __init__(self, outer_instance):
            self.outer_instance = outer_instance
            self.profiles = {}
            self.incompatible_profiles = []
            stored_profs = self.outer_instance.config.get_prefix_sections('pid_profile %s' % self.outer_instance.short_name)
            for profile in stored_profs:
                self._init_profile(profile, profile.get_name().split(' ', 2)[-1])
    
        def _init_profile(self, config_section, name):
            version = config_section.getint('pid_version', 1)
            if version != PID_PROFILE_VERSION:
                logging.info('Profile [%s] not compatible with this version of pid_profile.\nProfile Version: %d Current Version: %d' % (name, version, PID_PROFILE_VERSION))
                self.incompatible_profiles.append(name)
                return None
            temp_profile = {}
            control = self._check_value_config('control', config_section, str, False)
            if control == 'watermark':
                temp_profile['max_delta'] = config_section.getfloat('max_delta', 2.0, above=0.0)
            elif control == 'mpc':
                temp_profile['block_heat_capacity'] = config_section.getfloat('block_heat_capacity', above=0.0, default=None)
                temp_profile['ambient_transfer'] = config_section.getfloat('ambient_transfer', minval=0.0, default=None)
                temp_profile['target_reach_time'] = config_section.getfloat('target_reach_time', above=0.0, default=2.0)
                temp_profile['smoothing'] = config_section.getfloat('smoothing', above=0.0, maxval=1.0, default=0.83)
                temp_profile['heater_power'] = config_section.getfloat('heater_power', above=0.0)
                temp_profile['sensor_responsiveness'] = config_section.getfloat('sensor_responsiveness', above=0.0, default=None)
                temp_profile['min_ambient_change'] = config_section.getfloat('min_ambient_change', above=0.0, default=1.0)
                temp_profile['steady_state_rate'] = config_section.getfloat('steady_state_rate', above=0.0, default=0.5)
                temp_profile['filament_diameter'] = config_section.getfloat('filament_diameter', above=0.0, default=1.75)
                temp_profile['filament_density'] = config_section.getfloat('filament_density', above=0.0, default=1.2)
                temp_profile['filament_heat_capacity'] = config_section.getfloat('filament_heat_capacity', above=0.0, default=1.8)
                temp_profile['maximum_retract'] = config_section.getfloat('maximum_retract', above=0.0, default=2.0)
                filament_temp_src_raw = config_section.get('filament_temperature_source', 'ambient')
                temp = filament_temp_src_raw.lower().strip()
                if temp == 'sensor':
                    filament_temp_src = (FILAMENT_TEMP_SRC_SENSOR,)
                elif temp == 'ambient':
                    filament_temp_src = (FILAMENT_TEMP_SRC_AMBIENT,)
                else:
                    try:
                        value = float(temp)
                    except ValueError:
                        raise config_section.error(f"Unable to parse option 'filament_temperature_source' in section '{config_section.get_name()}'")
                    filament_temp_src = (FILAMENT_TEMP_SRC_FIXED, value)
                temp_profile['filament_temp_src'] = filament_temp_src
                ambient_sensor_name = config_section.get('ambient_temp_sensor', None)
                ambient_sensor = None
                if ambient_sensor_name is not None:
                    ambient_sensor = config_section.get_printer().load_object(config_section, ambient_sensor_name, None)
                    if ambient_sensor is None:
                        ambient_sensor = config_section.get_printer().lookup_object(ambient_sensor_name, None)
                    if ambient_sensor is None:
                        raise config_section.error(f"Unknown ambient_temp_sensor '{ambient_sensor_name}' specified")
                temp_profile['ambient_temp_sensor'] = ambient_sensor
                fan_name = config_section.get('cooling_fan', None)
                fan = None
                if fan_name is not None:
                    fan_obj = config_section.get_printer().load_object(config_section, fan_name, None)
                    if fan_obj is None:
                        fan_obj = config_section.get_printer().lookup_object(fan_name, None)
                    if fan_obj is None:
                        raise config_section.error(f"Unknown part_cooling_fan '{fan_name}' specified")
                    if not hasattr(fan_obj, 'fan') or not hasattr(fan_obj.fan, 'set_speed'):
                        raise config_section.error(f"part_cooling_fan '{fan_name}' is not a valid fan object")
                    fan = fan_obj.fan
                temp_profile['cooling_fan'] = fan
                temp_profile['fan_ambient_transfer'] = config_section.getfloatlist('fan_ambient_transfer', [])
            elif control == 'pid' or control == 'pid_v':
                for key, (type, placeholder) in PID_PROFILE_OPTIONS.items():
                    can_be_none = key != 'pid_kp' and key != 'pid_ki' and (key != 'pid_kd')
                    temp_profile[key] = self._check_value_config(key, config_section, type, can_be_none)
                if name == 'default':
                    temp_profile['smooth_time'] = None
            elif control == 'dual_loop_pid':
                for key, (type, placeholder) in PID_PROFILE_OPTIONS.items():
                    can_be_none = key not in ['pid_kp', 'pid_ki', 'pid_kd']
                    temp_profile[key] = self._check_value_config(key, config_section, type, can_be_none)
                    if key in ['pid_kp', 'pid_ki', 'pid_kd']:
                        inner_key = 'inner_' + key
                        temp_profile[inner_key] = self._check_value_config(inner_key, config_section, type, can_be_none)
                if name == 'default':
                    temp_profile['smooth_time'] = None
            else:
                raise self.outer_instance.printer.config_error("Unknown control type '%s' in [pid_profile %s %s]." % (control, self.outer_instance.short_name, name))
            temp_profile['control'] = control
            temp_profile['name'] = name
            self.profiles[name] = temp_profile
            return temp_profile
    
        def _check_value_config(self, key, config_section, type, can_be_none):
            if type is int:
                value = config_section.getint(key, None)
            elif type is float:
                value = config_section.getfloat(key, None)
            else:
                value = config_section.get(key, None)
            if not can_be_none and value is None:
                raise self.outer_instance.gcode.error("pid_profile: '%s' has to be specified in [pid_profile %s %s]." % (key, self.outer_instance.short_name, config_section.get_name()))
            return value
    
        def _compute_section_name(self, profile_name):
            return self.outer_instance.short_name if profile_name == 'default' else 'pid_profile ' + self.outer_instance.short_name + ' ' + profile_name
    
        def _check_value_gcmd(self, name, default, gcmd, type, can_be_none, minval=None, maxval=None):
            if type is int:
                value = gcmd.get_int(name, default, minval=minval, maxval=maxval)
            elif type is float:
                value = gcmd.get_float(name, default, minval=minval, maxval=maxval)
            else:
                value = gcmd.get(name, default)
            if not can_be_none and value is None:
                raise self.outer_instance.gcode.error("pid_profile: '%s' has to be specified." % name)
            return value.lower() if type == 'lower' else value
    
        def init_default_profile(self):
            return self._init_profile(self.outer_instance.config, 'default')
    
        def set_values(self, profile_name, gcmd, verbose):
            current_profile = self.outer_instance.get_control().get_profile()
            target = self._check_value_gcmd('TARGET', None, gcmd, float, False)
            tolerance = self._check_value_gcmd('TOLERANCE', current_profile['pid_tolerance'], gcmd, float, False)
            control = self._check_value_gcmd('CONTROL', current_profile['control'], gcmd, 'lower', False)
            kp = self._check_value_gcmd('KP', None, gcmd, float, False)
            ki = self._check_value_gcmd('KI', None, gcmd, float, False)
            kd = self._check_value_gcmd('KD', None, gcmd, float, False)
            smooth_time = self._check_value_gcmd('SMOOTH_TIME', None, gcmd, float, True)
            keep_target = self._check_value_gcmd('KEEP_TARGET', 0, gcmd, int, True, minval=0, maxval=1)
            load_clean = self._check_value_gcmd('LOAD_CLEAN', 0, gcmd, int, True, minval=0, maxval=1)
            temp_profile = {'pid_target': target, 'pid_tolerance': tolerance, 'control': control, 'smooth_time': smooth_time, 'pid_kp': kp, 'pid_ki': ki, 'pid_kd': kd}
            if control == 'dual_loop_pid':
                inner_kp = self._check_value_gcmd('INNER_KP', current_profile.get('inner_pid_kp'), gcmd, float, False)
                inner_ki = self._check_value_gcmd('INNER_KI', current_profile.get('inner_pid_ki'), gcmd, float, False)
                inner_kd = self._check_value_gcmd('INNER_KD', current_profile.get('inner_pid_kd'), gcmd, float, False)
                temp_profile['inner_pid_kp'] = inner_kp
                temp_profile['inner_pid_ki'] = inner_ki
                temp_profile['inner_pid_kd'] = inner_kd
            temp_control = self.outer_instance.lookup_control(temp_profile, load_clean)
            self.outer_instance.set_control(temp_control, keep_target)
            msg = 'PID Parameters:\nTarget: %.2f,\nTolerance: %.4f\nControl: %s\n' % (target, tolerance, control)
            if smooth_time is not None:
                msg += 'Smooth Time: %.3f\n' % smooth_time
            msg += 'pid_Kp=%.3f pid_Ki=%.3f pid_Kd=%.3f\n' % (kp, ki, kd)
            if control == 'dual_loop_pid':
                msg += 'inner_pid_Kp=%.3f inner_pid_Ki=%.3f inner_pid_Kd=%.3f\n' % (inner_kp, inner_ki, inner_kd)
            msg += 'have been set as current profile.'
            self.outer_instance.gcode.respond_info(msg)
            self.save_profile(profile_name=profile_name, verbose=True)
    
        def _profile_fields_msg(self, profile):
            msg = 'Control: %s\n' % (profile['control'],)
            for key, value in sorted(profile.items()):
                if key in ('control', 'name') or value is None:
                    continue
                if isinstance(value, (int, float, str)):
                    msg += '%s: %s\n' % (key, value)
            msg += 'name: %s' % (profile['name'],)
            return msg
    
        def get_values(self, profile_name, gcmd, verbose):
            temp_profile = self.outer_instance.get_control().get_profile()
            if temp_profile['control'] not in PID_CONTROL_TYPES:
                self.outer_instance.gcode.respond_info(self._profile_fields_msg(temp_profile))
                return
            target = temp_profile['pid_target']
            tolerance = temp_profile['pid_tolerance']
            control = temp_profile['control']
            kp = temp_profile['pid_kp']
            ki = temp_profile['pid_ki']
            kd = temp_profile['pid_kd']
            smooth_time = self.outer_instance.get_smooth_time() if temp_profile['smooth_time'] is None else temp_profile['smooth_time']
            name = temp_profile['name']
            msg = 'PID Parameters:\nTarget: %.2f,\nTolerance: %.4f\nControl: %s\nSmooth Time: %.3f\npid_Kp=%.3f pid_Ki=%.3f pid_Kd=%.3f\n' % (target, tolerance, control, smooth_time, kp, ki, kd)
            if control == 'dual_loop_pid':
                msg += 'inner_pid_Kp=%.3f inner_pid_Ki=%.3f inner_pid_Kd=%.3f\n' % (temp_profile['inner_pid_kp'], temp_profile['inner_pid_ki'], temp_profile['inner_pid_kd'])
            msg += 'name: %s' % name
            self.outer_instance.gcode.respond_info(msg)
    
        def save_profile(self, profile_name=None, gcmd=None, verbose=True):
            temp_profile = self.outer_instance.get_control().get_profile()
            control = temp_profile['control']
            if control not in PID_CONTROL_TYPES and control != 'watermark':
                self.outer_instance.gcode.respond_info('Saving [%s] profiles with PID_PROFILE SAVE is not supported.' % (control,))
                return
            if profile_name is None:
                profile_name = temp_profile['name']
            section_name = self._compute_section_name(profile_name)
            self.outer_instance.configfile.set(section_name, 'pid_version', PID_PROFILE_VERSION)
            if control == 'watermark':
                self.outer_instance.configfile.set(section_name, 'control', control)
                self.outer_instance.configfile.set(section_name, 'max_delta', '%.4f' % (temp_profile['max_delta'],))
            else:
                is_dual_loop = control == 'dual_loop_pid'
                for key, (type, placeholder) in PID_PROFILE_OPTIONS.items():
                    value = temp_profile[key]
                    if value is not None:
                        self.outer_instance.configfile.set(section_name, key, placeholder % value)
                    if is_dual_loop and key in ('pid_kp', 'pid_ki', 'pid_kd'):
                        inner_key = 'inner_' + key
                        inner_value = temp_profile.get(inner_key)
                        if inner_value is not None:
                            self.outer_instance.configfile.set(section_name, inner_key, placeholder % inner_value)
            temp_profile['name'] = profile_name
            self.profiles[profile_name] = temp_profile
            if verbose:
                self.outer_instance.gcode.respond_info('Current PID profile for heater [%s] has been saved to profile [%s] for the current session.  The SAVE_CONFIG command will\nupdate the printer config file and restart the printer.' % (self.outer_instance.short_name, profile_name))
    
        def load_profile(self, profile_name, gcmd, verbose):
            verbose = self._check_value_gcmd('VERBOSE', 'low', gcmd, 'lower', True)
            load_clean = self._check_value_gcmd('LOAD_CLEAN', 0, gcmd, int, True, minval=0, maxval=1)
            if profile_name == self.outer_instance.get_control().get_profile()['name'] and (not load_clean):
                if verbose == 'high' or verbose == 'low':
                    self.outer_instance.gcode.respond_info('PID Profile [%s] already loaded for heater [%s].' % (profile_name, self.outer_instance.short_name))
                return
            keep_target = self._check_value_gcmd('KEEP_TARGET', 0, gcmd, int, True, minval=0, maxval=1)
            profile = self.profiles.get(profile_name, None)
            defaulted = False
            default = gcmd.get('DEFAULT', None)
            if profile is None:
                if default is None:
                    raise self.outer_instance.gcode.error('pid_profile: Unknown profile [%s] for heater [%s].' % (profile_name, self.outer_instance.short_name))
                profile = self.profiles.get(default, None)
                defaulted = True
                if profile is None:
                    raise self.outer_instance.gcode.error('pid_profile: Unknown default profile [%s] for heater [%s].' % (default, self.outer_instance.short_name))
            control = self.outer_instance.lookup_control(profile, load_clean)
            self.outer_instance.set_control(control, keep_target)
            if verbose != 'high' and verbose != 'low':
                return
            if defaulted:
                self.outer_instance.gcode.respond_info("Couldn't find profile [%s] for heater [%s], defaulted to [%s]." % (profile_name, self.outer_instance.short_name, default))
            self.outer_instance.gcode.respond_info('PID Profile [%s] loaded for heater [%s].\n' % (profile['name'], self.outer_instance.short_name))
            if verbose == 'high':
                if profile['control'] not in PID_CONTROL_TYPES:
                    self.outer_instance.gcode.respond_info(self._profile_fields_msg(profile))
                    return
                smooth_time = self.outer_instance.get_smooth_time() if profile['smooth_time'] is None else profile['smooth_time']
                msg = 'Target: %.2f\nTolerance: %.4f\nControl: %s\n' % (profile['pid_target'], profile['pid_tolerance'], profile['control'])
                if smooth_time is not None:
                    msg += 'Smooth Time: %.3f\n' % smooth_time
                msg += 'PID Parameters: pid_Kp=%.3f pid_Ki=%.3f pid_Kd=%.3f\n' % (profile['pid_kp'], profile['pid_ki'], profile['pid_kd'])
                if profile['control'] == 'dual_loop_pid':
                    msg += 'Inner PID Parameters: inner_pid_Kp=%.3f inner_pid_Ki=%.3f inner_pid_Kd=%.3f\n' % (profile['inner_pid_kp'], profile['inner_pid_ki'], profile['inner_pid_kd'])
                self.outer_instance.gcode.respond_info(msg)
    
        def remove_profile(self, profile_name, gcmd, verbose):
            if profile_name in self.profiles:
                section_name = self._compute_section_name(profile_name)
                self.outer_instance.configfile.remove_section(section_name)
                profiles = dict(self.profiles)
                del profiles[profile_name]
                self.profiles = profiles
                self.outer_instance.gcode.respond_info('Profile [%s] for heater [%s] removed from storage for this session.\nThe SAVE_CONFIG command will update the printer\nconfiguration and restart the printer' % (profile_name, self.outer_instance.short_name))
            else:
                self.outer_instance.gcode.respond_info('No profile named [%s] to remove' % profile_name)
        cmd_PID_PROFILE_help = 'PID Profile Persistent Storage management'
    
        def cmd_PID_PROFILE(self, gcmd):
            options = collections.OrderedDict({'LOAD': self.load_profile, 'SAVE': self.save_profile, 'GET_VALUES': self.get_values, 'SET_VALUES': self.set_values, 'REMOVE': self.remove_profile})
            for key in options:
                profile_name = gcmd.get(key, None)
                if profile_name is not None:
                    if not profile_name.strip():
                        raise self.outer_instance.gcode.error('pid_profile: Profile must be specified')
                    options[key](profile_name, gcmd, True)
                    return
            raise self.outer_instance.gcode.error("pid_profile: Invalid syntax '%s'" % (gcmd.get_commandline(),))
    can_extrude = _k.Attr(2233, 'can_extrude')
